'use strict';
const $=s=>document.querySelector(s), cfg=window.APP_CONFIG||{};
const client=window.HVT;
const configured=client.configured;
const base=client.base;
const readLocal=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let saved=readLocal('hvt-saved',[]); if(!Array.isArray(saved))saved=[];
let readerToken=0;
let filter='all', onlySaved=false, items=[];
const demo=[{id:'hvt-hieu-thuong',kind:'sach',title:'Hiểu để thương, thương để trở về',author:'Hiểu & Thương',description:'Một bài viết nhỏ về sự lắng nghe và những điều giữ cho tình thân được ấm áp.',body:'Có lúc, điều người bên cạnh cần không phải là một lời khuyên, mà là cảm giác mình đang được lắng nghe.\n\nHãy thử ngồi xuống, đặt những phán xét sang một bên và nghe trọn một câu chuyện. Hỏi thêm một câu để hiểu, thay vì vội vàng đưa ra kết luận.\n\nHiểu không đến chỉ từ việc biết thật nhiều. Hiểu còn đến từ việc nhận ra rằng kinh nghiệm của mình chưa phải toàn bộ câu chuyện. Người trước mặt ta có những niềm vui, nỗi sợ và khó khăn mà ta chưa từng sống qua.\n\nKhi hiểu thêm một chút, ta thường có thể thương bằng cách cụ thể hơn: nói chậm lại, hỏi thăm đúng lúc, giúp một việc nhỏ, hoặc tôn trọng một khoảng lặng.\n\nBài viết do Hiểu & Thương biên soạn. Nội dung minh họa thư viện, không phải kinh điển.'},{id:'hvt-biet-on',kind:'sach',title:'Một ngày sống với lòng biết ơn',author:'Hiểu & Thương',description:'Ba khoảng dừng giản dị để nhận ra những điều đang nâng đỡ cuộc sống mình.',body:'Buổi sáng, trước khi bắt đầu công việc, hãy nhận ra một điều đang nâng đỡ mình: một bữa ăn, một người thân, hay một cơ thể vẫn đang cố gắng.\n\nGiữa ngày, dành một khoảng dừng để cảm ơn ai đó bằng một câu thật cụ thể. “Cảm ơn bạn vì đã dành thời gian giúp tôi.” Sự cụ thể khiến lòng biết ơn trở thành một cuộc gặp gỡ.\n\nBuổi tối, nhớ lại một việc lành mình đã nhận và một việc lành mình có thể tiếp nối. Không cần một ngày hoàn hảo để có thể biết ơn. Ta vẫn có thể nhìn nhận điều khó khăn, đồng thời trân trọng những gì đã giúp mình đi qua.\n\nBài viết do Hiểu & Thương biên soạn. Nội dung minh họa thư viện, không phải kinh điển.'}];
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function url(s){try{const u=new URL(s);return u.protocol==='https:'?u:null}catch{return null}}
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function persistSaved(){try{localStorage.setItem('hvt-saved',JSON.stringify(saved))}catch{notify('Trình duyệt không cho phép lưu dấu trang.')}}
async function load(){if(!configured){items=demo;render();return}$('#libraryNotice').textContent='Đang tải thư viện…';try{items=await client.resources();render()}catch(e){items=[];render();$('#libraryNotice').textContent='Chưa tải được thư viện. Vui lòng thử lại sau.';console.warn('Library request failed')}}
function render(){const q=$('#search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();const list=items.filter(i=>(filter==='all'||i.kind===filter)&&(!onlySaved||saved.includes(i.id))&&[i.title,i.author,i.description].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().includes(q));$('#savedCount').textContent=saved.length;$('#savedBtn').classList.toggle('active',onlySaved);document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===filter;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});$('#libraryNotice').textContent=(onlySaved?'Đang xem mục đã lưu · ':'')+(configured?list.length+' nội dung':'Bản xem trước · 2 bài viết minh họa do Hiểu & Thương biên soạn. Kinh và video sẽ xuất hiện khi được thêm.');$('#cards').innerHTML=list.length?list.map(i=>`<article class="card"><div class="card-art ${i.kind==='video'?'video-cover':'book-cover'}">${client.cover(i)?`<img src="${esc(client.cover(i))}" alt="${esc(i.title)}" loading="lazy">`:''}<span>${i.kind==='video'?'▷':i.kind==='kinh'?'❋':'☷'}</span></div><div class="card-body"><span class="tag">${i.kind==='kinh'?'KINH':i.kind==='video'?'VIDEO':'TRANG ĐỌC'}</span><h3>${esc(i.title)}</h3><p>${esc(i.description)}</p><p>${esc(i.author)}</p><div class="card-bottom"><button class="text-link open-item" data-id="${esc(i.id)}">${i.kind==='video'?'Xem video':'Mở trang đọc'} ↗</button><button class="bookmark" data-id="${esc(i.id)}" aria-label="${saved.includes(i.id)?'Bỏ lưu':'Lưu'} ${esc(i.title)}" aria-pressed="${saved.includes(i.id)}">${saved.includes(i.id)?'♥':'♡'}</button></div></div></article>`).join(''):`<div class="empty"><div>❋</div><h3>${q?'Chưa tìm thấy nội dung phù hợp':onlySaved?'Chưa có nội dung đã lưu':'Thư viện đang chờ những trang đầu tiên'}</h3><p>${q?'Hãy thử một từ khóa khác.':onlySaved?'Chạm vào trái tim bên cạnh bài viết để lưu trên thiết bị này.':'Kinh, sách và video đã được kiểm tra nguồn sẽ được bổ sung tại đây.'}</p></div>`}
function videoEmbed(value){const u=url(value);if(!u)return null;let id;if(['youtube.com','www.youtube.com','m.youtube.com'].includes(u.hostname)){id=u.pathname==='/watch'?u.searchParams.get('v'):u.pathname.match(/^\/(?:shorts|embed|live)\/([^/]+)/)?.[1]}else if(u.hostname==='youtu.be')id=u.pathname.slice(1).split('/')[0];if(id&&/^[A-Za-z0-9_-]{11}$/.test(id))return 'https://www.youtube-nocookie.com/embed/'+id;if(['vimeo.com','www.vimeo.com'].includes(u.hostname)){const match=u.pathname.match(/^\/(\d+)\/?$/);if(match)return 'https://player.vimeo.com/video/'+match[1]}return null}
async function openItem(id){const token=++readerToken;window.HVTProgress?.close();window.HVTCommunity?.close();const i=items.find(x=>x.id===id);if(!i)return;const u=url(i.url), embed=i.kind==='video'?videoEmbed(i.url):null;let media=!i.video_series&&client.cover(i)?`<img class="reader-cover" src="${esc(client.cover(i))}" alt="Bìa ${esc(i.title)}">`:'';if(embed&&!i.video_series)media+=`<iframe src="${esc(embed)}" title="${esc(i.title)}" allow="fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;else if(i.kind==='video'&&!i.video_series&&u&&/\.(mp4|webm)$/i.test(u.pathname))media+=`<video src="${esc(u.href)}" controls preload="metadata"></video>`;else if(i.kind==='video'&&!i.video_series&&u)media+='<p>Video này được xem trên trang nguồn. Nhấn liên kết bên dưới để mở.</p>';if(i.file_path)media+=`<p><a data-pdf-link class="button primary" target="_blank" rel="noopener noreferrer" href="${esc(base+'/storage/v1/object/public/documents/'+i.file_path.split('/').map(encodeURIComponent).join('/'))}">Mở tài liệu PDF ↗</a></p>`;$('#readerContent').innerHTML=`<span class="eyebrow">${i.kind==='video'?'LẮNG NGHE':'TRANG ĐỌC'}</span><h2>${esc(i.title)}</h2><p>${esc(i.author)}</p>${i.kind!=='video'?`<p><a class="text-link" href="/chep-kinh.html?book=${encodeURIComponent(i.id)}">Chép Kinh / Sách này ↗</a></p>`:''}${media}${i.body_html?`<div class="rich-document">${window.HVTRich.clean(i.body_html)}</div>`:`<div class="body-text">${esc(i.body||i.description)}</div>`}${u?`<p class="source"><a class="text-link" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Mở nguồn gốc ↗</a></p>`:''}`;$('#reader').classList.toggle('chapter-reader',i.reading_mode==='sections');$('#reader').showModal();if(i.kind==='video'&&i.video_series)window.HVTVideoSeries?.attach(i,$('#readerContent'),()=>token===readerToken);else window.HVTCommunity?.open(i,$('#readerContent'));if(i.reading_mode!=='sections')await window.HVTProgress?.attach({item:i,container:$('#readerContent'),dialog:$('#reader'),isCurrent:()=>token===readerToken});if(i.reading_mode==='sections'){const host=document.createElement('section');host.className='reader-sections';host.innerHTML='<p role="status">Đang tải các trang/phần đã công khai…</p>';$('#readerContent').append(host);try{const parts=await window.HVTSections.publicSections(i.id);if(token!==readerToken)return;if(!parts.length){host.innerHTML='<p class="chapter-empty">Chưa có trang/phần công khai. Các phần đang soạn sẽ xuất hiện khi hoàn thành.</p>';return}let index=0;function draw(){const part=parts[index];window.HVTProgress?.section(part.id);window.HVTCommunity?.section(part.id);const title=p=>(p.label?p.label+' '+p.number+' · ':'')+'Trang '+(p.page_order||p.number)+(p.title?' — '+p.title:'');host.innerHTML=`<div class="reader-chapter-header"><p class="eyebrow">MỤC LỤC · ${parts.length} PHẦN ĐÃ CÔNG KHAI</p><label>Chọn trang / phần<select id="readerSectionSelect" aria-label="Chọn trang hoặc Chương Phẩm">${parts.map((p,n)=>`<option value="${n}" ${n===index?'selected':''}>${esc(title(p))}</option>`).join('')}</select></label></div><article class="chapter-article"><h3>${esc(title(part))}</h3><div class="rich-document">${window.HVTRich.clean(part.body_html)}</div></article><div class="chapter-navigation"><button type="button" class="button secondary" data-step="-1" ${index===0?'disabled':''}>← Phần trước</button><span>${index+1} / ${parts.length}</span><button type="button" class="button secondary" data-step="1" ${index===parts.length-1?'disabled':''}>Phần tiếp →</button></div>`;host.querySelector('select').onchange=e=>{index=Number(e.target.value);draw();$('#reader').scrollTop=host.offsetTop};host.querySelectorAll('[data-step]').forEach(btn=>btn.onclick=()=>{index+=Number(btn.dataset.step);draw();$('#reader').scrollTop=host.offsetTop})}draw();await window.HVTProgress?.attach({item:i,container:$('#readerContent'),dialog:$('#reader'),parts,selectSection:n=>{index=n;draw()},isCurrent:()=>token===readerToken});if(token===readerToken){const requested=new URLSearchParams(location.search);if(requested.get('read')===i.id&&requested.get('section')){const n=parts.findIndex(p=>p.id===requested.get('section'));if(n>=0){index=n;draw()}}window.HVTProgress?.section(parts[index].id);window.HVTCommunity?.section(parts[index].id)}}catch{if(token===readerToken)host.innerHTML='<p role="status">Chưa tải được Chương/Phẩm. Vui lòng thử lại sau.</p>'}}}
function route(){const h=location.hash.slice(1)||'home';if(['kinh','sach','video'].includes(h)){filter=h;onlySaved=false;render();$('#library').scrollIntoView({behavior:'smooth'})}document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===h))}
$('#readArticle').onclick=()=>{const more=$('#articleMore');more.hidden=!more.hidden;$('#readArticle').textContent=more.hidden?'Đọc tiếp bài viết ↗':'Thu gọn bài viết ↑'};
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#reader').addEventListener('close',()=>{readerToken++;window.HVTProgress?.close();window.HVTCommunity?.close();$('#readerContent').innerHTML=''});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#search').oninput=render;$('#savedBtn').onclick=()=>{onlySaved=!onlySaved;filter='all';render();$('#library').scrollIntoView({behavior:'smooth'})};$('#cards').onclick=e=>{const open=e.target.closest('.open-item'),mark=e.target.closest('.bookmark');if(open)openItem(open.dataset.id);if(mark){saved=saved.includes(mark.dataset.id)?saved.filter(id=>id!==mark.dataset.id):[...saved,mark.dataset.id];persistSaved();render()}};window.addEventListener('hashchange',route);
load().then(()=>{const requested=new URLSearchParams(location.search).get('read');if(requested){if(items.some(i=>i.id===requested))openItem(requested);else notify('Nội dung được chia sẻ không còn trong thư viện hoặc chưa tải được.')}});route();
